INSERT INTO public.churches (id, slug, name, patron_saint, address, cover_path, logo_path, accent_color, history_summary, history_full, founded_year, is_active, sort_order)
VALUES
  ('demo-church-1', 'catedral-san-ildefonso', 'Catedral de San Ildefonso', 'San Ildefonso de Toledo y la Sede Apostólica', 'Calle 60 x 61 y 63, Centro Histórico (Plaza Grande), C.P. 97000, Mérida, Yucatán', '/images/churches/catedral-san-ildefonso.png', NULL, '#8B1E0F', 'Primera catedral levantada en la América continental y la más antigua de México. Erigida con los sillares de la antigua metrópoli maya de T''Hó, su imponente fábrica manierista y herreriana con aspecto de fortaleza custodia el venerado Santo Cristo de las Ampollas y el monumental Cristo de la Unidad.', 'La Santa Iglesia Catedral de San Ildefonso de Mérida ostenta la primacía histórica de ser la primera catedral erigida en la América continental sobre tierra firme. Su edificación fue autorizada por el papa Pío IV mediante la bula "Super Speculam Militantis Ecclesiae" en 1561 y encomendada a fray Francisco de Toral, primer obispo de Yucatán.
INSERT INTO public.heritage_objects (id, church_id, name, category, quantity, description, history, cover_path, visibility, status)
VALUES
  ('demo-object-1', 'demo-church-1', 'Cristo de la Unidad', 'escultura', 1, 'Colosal escultura de abedul de casi 12 metros de altura montada sobre una cruz de caoba yucateca de 14 metros, suspendida en el presbiterio central.', 'Creada a mediados del siglo XX por el insigne escultor español Ramón Lapayese para sustituir los retablos perdidos en 1915. Es considerado el crucifijo de madera bajo techo más grande de América.', 'https://upload.wikimedia.org/wikipedia/commons/a/ab/Catedral_de_M%C3%A9rida_%22San_Ildefonso%22_Siglo_XVI%2CM%C3%A9rida%2CEstado_de_Yucat%C3%A1n%2CM%C3%A9xico.jpg', 'publico', 'publicado'),
  ('demo-object-2', 'demo-church-1', 'Portada del Perdón con Escudo Real del Toisón de Oro', 'arquitectura', 1, 'Portada renacentista y manierista en cantera labrada que exhibe el escudo de los Reyes Católicos y la Casa de Austria con el águila bicéfala y el toisón.', 'Tallada en cantería de T''Hó a finales del siglo XVI por maestros canteros bajo la dirección de Pedro de Aulestia y Juan Miguel de Agüero.', 'https://upload.wikimedia.org/wikipedia/commons/d/df/Portada_occidental_de_la_Catedral_de_Astorga.jpg', 'publico', 'publicado'),
  ('demo-object-3', 'demo-church-1', 'Cruz Atrial de Piedra Virreinal', 'escultura', 1, 'Monolítica cruz atrial labrada en piedra caliza con bajorrelieves de la corona de espinas y los clavos de la pasión.', 'Testimonio del proceso de evangelización franciscana del siglo XVI, colocada en el patio para congregar a los indígenas mayas neófitos.', 'https://upload.wikimedia.org/wikipedia/commons/5/5b/Cruz_Atrial_y_Templo_de_San_Jer%C3%B3nimo_de_Huandacareo.jpg', 'publico', 'publicado'),
  ('demo-object-4', 'demo-church-1', 'Campana Mayor "San Ildefonso"', 'campana', 1, 'Campana histórica fundida en bronce con aleación de plata y sonoro tañido, ubicada en la torre norte.', 'Bendecida en la época virreinal, ha convocado a la oración y anunciado acontecimientos históricos desde el siglo XVII en Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/f/f9/Bernau_bei_Berlin_St._Marienkirche_Findling_Glockengussanlage.JPG', 'publico', 'publicado'),
  ('demo-object-5', 'demo-church-1', 'Custodia Procesional y Cálices de Plata Novohispana', 'orfebreria', 3, 'Aparato eucarístico de sol con rayos flamígeros e incrustaciones, acompañado de dos cálices cincelados con punzón de plateros virreinales.', 'Donados por cofradías catedralicias y obispos de Yucatán entre los siglos XVII y XVIII para las solemnidades del Corpus Christi.', 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Monstrancja_Jagie%C5%82%C5%82y.JPG', 'publico', 'publicado'),
  ('demo-object-6', 'demo-church-2', 'Murales Virreinales al Temple del Presbiterio', 'pintura', 4, 'Conjunto de pinturas murales sobre yeso que representan ángeles querubines, guirnaldas vegetales y pasajes bíblicos del Nuevo Testamento.', 'Ejecutados hacia 1622 por artistas novohispanos bajo la guía de los sacerdotes de la Compañía de Jesús para el adoctrinamiento visual.', 'https://upload.wikimedia.org/wikipedia/commons/6/67/Templo_San_Pedro_de_Pari.jpg', 'publico', 'publicado'),
  ('demo-object-7', 'demo-church-2', 'Sillares Mayas Prehispánicos de T''Hó con Bajorrelieves', 'arquitectura', 8, 'Bloques de piedra caliza con intrincadas grecas geométricas labradas por canteros mayas del posclásico visibles en los muros exteriores sobre la calle 59.', 'Extraídos de los adoratorios de la antigua urbe maya de T''Hó para levantar los muros de la capilla jesuita en 1618.', 'https://upload.wikimedia.org/wikipedia/commons/e/ec/Vestigios_mayas_en_la_Iglesia_de_la_3%C2%AA_Orden%2C_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg', 'publico', 'publicado'),
  ('demo-object-8', 'demo-church-2', 'Retablo Neobarroco Dorado de los Santos Jesuitas', 'retablo', 1, 'Retablo de madera tallada con estofado dorado en pan de oro, provisto de hornacinas conopiales y pilastras decoradas.', 'Erigido para rendir culto a San Ignacio y San Francisco Javier, adaptado con adiciones franciscanas tras 1767.', 'https://upload.wikimedia.org/wikipedia/commons/6/69/Rodez_-_Chapelle_de_l%27ancien_Coll%C3%A8ge_des_J%C3%A9suites_-_place_du_Mar%C3%A9chal_Foch_2_%2812-2015%29_P1030298.JPG', 'publico', 'publicado'),
  ('demo-object-9', 'demo-church-2', 'Pila Bautismal Monolítica de Cantera', 'escultura', 1, 'Gran taza bautismal tallada en un solo bloque de piedra caliza yucateca con cordón franciscano en relieve en el brocal.', 'Labrada en el siglo XVII para la administración bautismal en el recinto colonial anexo al Colegio de San Francisco Javier.', 'https://upload.wikimedia.org/wikipedia/commons/c/c5/Br%C3%A9an%C3%A7on_%2895%29%2C_%C3%A9glise_Saint-Cr%C3%A9pin-et-Saint-Cr%C3%A9pinien%2C_bas-c%C3%B4t%C3%A9_sud%2C_fonts_baptismaux_1.JPG', 'publico', 'publicado'),
  ('demo-object-10', 'demo-church-2', 'Cajonera Virreinal de Sacristía en Cedro y Caoba', 'mobiliario', 1, 'Mueble ebanístico de amplias gavetas ensamblado con maderas preciosas de la selva peninsular y herrajes de forja.', 'Custodiado ininterrumpidamente desde finales del siglo XVIII en la sacristía para el resguardo de ornamentos litúrgicos y casullas bordadas.', 'https://upload.wikimedia.org/wikipedia/commons/6/63/Cajonera_de_la_sacrist%C3%ADa_de_la_Cartuja_de_Granada.jpg', 'publico', 'publicado'),
  ('demo-object-11', 'demo-church-3', 'Retablo Mayor Churrigueresco en Madera Estofada en Oro', 'retablo', 1, 'Obra maestra del barroco novohispano estípite en madera de cedro recubierta de oro fino, con nichos calados y querubines.', 'Comisionado hacia 1710 por el gobernador Martín de Urzúa y devotos de las Islas Canarias, es el único retablo churrigueresco mayor que sobrevivió intacto en Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/f/f4/ICandelariaZafra%2C_Retablo_Mayor.jpg', 'publico', 'publicado'),
  ('demo-object-12', 'demo-church-3', 'Tórtolas y Resplandor de Plata de la Candelaria', 'orfebreria', 2, 'Par de aves rituales cinceladas en plata virreinal fina y corona con resplandor estrellado para la venerada imagen mariana.', 'Donación votiva efectuada en 1715 en testimonio de agradecimiento por el cese de una plaga en la península.', 'https://upload.wikimedia.org/wikipedia/commons/c/cc/Grant_Wood_-_American_Gothic_-_Google_Art_Project.jpg', 'publico', 'publicado'),
  ('demo-object-13', 'demo-church-3', 'Púlpito Barroco de Madera Policromada', 'mobiliario', 1, 'Tribuna octagonal volada con escenas en relieve de los cuatro evangelistas y tornavoz rematado por la paloma eucarística.', 'Talla colonial realizada a mediados del siglo XVIII por imagineros peninsulares para la predicación en las festividades marianas.', 'https://upload.wikimedia.org/wikipedia/commons/b/b8/Catedral_de_Tulancingo_%22San_Juan_Bautista%22_en_Tulancingo%2C_Estado_de_Hidalgo%2C_M%C3%A9xico._02.jpg', 'publico', 'publicado'),
  ('demo-object-14', 'demo-church-3', 'Lienzo Colonial de la Presentación de Jesús en el Templo', 'pintura', 1, 'Pintura al óleo sobre tela que ilustra al venerable anciano Simeón y a la profetisa Ana proclamando a Jesús como luz de las naciones.', 'Cuadro virreinal del siglo XVIII perteneciente a la escuela pictórica yucateca, ubicado en el muro lateral del presbiterio.', 'https://upload.wikimedia.org/wikipedia/commons/5/5e/Master_of_the_Cini_Madonna_-_Presentation_of_Jesus_at_the_Temple_-_Google_Art_Project.jpg', 'publico', 'publicado'),
  ('demo-object-15', 'demo-church-3', 'Espadaña Mixtilínea con Campanas Coloniales', 'campana', 3, 'Cuerpo de tres vanos de medio punto coronado por roleos y almenas con tres campanas de bronce fundidas en 1706.', 'Remate campanario que rige los toques litúrgicos de la alborada del 2 de febrero y las convocatorias a misa en el barrio.', 'https://upload.wikimedia.org/wikipedia/commons/3/3d/Espada%C3%B1a_%28campanario%29_del_Templo_de_San_Diego_y_Templo_de_la_Tercera_orden_01.jpg', 'publico', 'publicado'),
  ('demo-object-16', 'demo-church-4', 'Monumental Espadaña Calada de Tres Arcos', 'arquitectura', 1, 'Frontispicio triangular escalonado con tres amplios vanos para campanas, rematado con una cruz de cantera y almenas laterales.', 'Construida entre 1575 y 1620, es una de las estampas más emblemáticas de la arquitectura virreinal yucateca.', 'https://upload.wikimedia.org/wikipedia/commons/f/f7/Iglesia_de_Santa_Lucia%2C_Fachada.jpg', 'publico', 'publicado'),
  ('demo-object-17', 'demo-church-4', 'Santo Cristo en Pasta de Caña de Maíz', 'escultura', 1, 'Escultura crucificada ligera elaborada con la técnica novohispana de pasta de caña y orquídeas, con gran patetismo en las heridas.', 'Talla del siglo XVII muy venerada por la antigua hermandad de negros y morenos libres que administraba la cofradía del templo.', 'https://upload.wikimedia.org/wikipedia/commons/6/6a/Santa_Iglesia_Catedral%2CMorelia%2CEstado_de_Michoac%C3%A1n%2CM%C3%A9xico.jpg', 'publico', 'publicado'),
  ('demo-object-18', 'demo-church-4', 'Lápida Testimonial del Cementerio General de 1804', 'otro', 1, 'Placa conmemorativa de piedra caliza empotrada que atestigua el uso del atrio como camposanto oficial de la ciudad de Mérida.', 'Colocada al fundarse el cementerio en 1804 bajo la administración del obispo Pedro Agustín Estévez y Ugarte para suspender los entierros dentro de las naves.', 'https://upload.wikimedia.org/wikipedia/commons/6/60/Gravestone_at_St_Nicholas_Church%2C_Henstridge_-_geograph.org.uk_-_703083.jpg', 'publico', 'publicado'),
  ('demo-object-19', 'demo-church-4', 'Campana Colonial "Santa María de la Asunción" (1764)', 'campana', 1, 'Campana de bronce con relieves de la Asunción de María y leyenda fundacional en caracteres latinos virreinales.', 'Fundida en talleres de Mérida en 1764 gracias a la limosna colectada entre vecinos y hacendados de los contornos.', 'https://upload.wikimedia.org/wikipedia/commons/7/7e/Universidad_de_Alcal%C3%A1_%28RPS_14-06-2020%29_fachada_de_la_Capilla_de_San_Ildefonso.png', 'publico', 'publicado'),
  ('demo-object-20', 'demo-church-4', 'Patena y Cetro de Plata de Santa Lucía', 'orfebreria', 2, 'Concha de plata repujada donde reposan los ojos votivos de la mártir y báculo pastoral plateado para las procesiones.', 'Piezas de orfebrería de plata donadas en el siglo XVIII por fieles agradecidos por la sanación de dolencias de la vista.', 'https://upload.wikimedia.org/wikipedia/commons/5/52/Byzantine_-_Paten_-_Walters_57644.jpg', 'publico', 'publicado'),
  ('demo-object-21', 'demo-church-5', 'Espadaña Esquinada Asimétrica', 'arquitectura', 1, 'Singular torre de campanas desplantada sobre la arista exterior noroeste del templo, rasgo casi inédito en la arquitectura religiosa de la ciudad.', 'Diseñada hacia 1690 para proyectar las campanas hacia las dos calles que bordeaban el Hospital Real de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/9/9c/Parroquia_San_Rom%C3%A1n_Martir_%28Campeche%29_Estado_de_Campeche%2C_M%C3%A9xico.jpg', 'publico', 'publicado'),
  ('demo-object-22', 'demo-church-5', 'Crucifijo de Mesa en Marfil y Ébano Hispano-Filipino', 'escultura', 1, 'Cruz procesional y de mesa con Cristo finamente tallado en marfil asiático con cantoneras y base de ébano con incrustaciones.', 'Arribado a Yucatán en el siglo XVII por la ruta comercial de la Nao de China, acompañaba el viático de los enfermos terminales en las salas del hospital.', 'https://upload.wikimedia.org/wikipedia/commons/1/18/Cristo_crucificado%2C_Museo_de_las_Ferias_%28Medina_del_Campo%29.jpg', 'publico', 'publicado'),
  ('demo-object-23', 'demo-church-5', 'Pila de Agua Bendita con Concha de Peregrino en Cantera', 'escultura', 2, 'Pila labrada en piedra caliza dura con motivos marinos de venera y acantos entrelazados.', 'Colocada a la entrada del templo hospitalario a finales del siglo XVII para la purificación de médicos, enfermeros y fieles.', 'https://upload.wikimedia.org/wikipedia/commons/c/c5/ImusCathedraljf0306_03.JPG', 'publico', 'publicado'),
  ('demo-object-24', 'demo-church-5', 'Libro de Registros y Defunciones del Hospital Real (Facsímil)', 'otro', 1, 'Libro empastado en cuero con registros manuscritos de ingresos de tropa, víctimas de la fiebre amarilla y socorros de guerra.', 'Valioso acervo testimonial conservado que da cuenta de la atención médica caritativa brindada por los hermanos juaninos.', 'https://upload.wikimedia.org/wikipedia/commons/6/6c/St_Helen%27s_church_-_geograph.org.uk_-_725147.jpg', 'publico', 'publicado'),
  ('demo-object-25', 'demo-church-5', 'Campana Litúrgica de la Orden Hospitalaria (1702)', 'campana', 1, 'Campana de bronce fundido con el emblema de la granada y la cruz patada de los religiosos hospitalarios de San Juan de Dios.', 'Tocaba históricamente para convocar a los médicos y enfermeros ante la llegada de heridos durante las sublevaciones coloniales.', 'https://upload.wikimedia.org/wikipedia/commons/b/bc/Santorin_%28GR%29%2C_Akrotiri%2C_Kapelle_--_2017_--_2970.jpg', 'publico', 'publicado'),
  ('demo-object-26', 'demo-church-6', 'Basamento Piramidal Maya Prehispánico Subyacente', 'arquitectura', 1, 'Gran plataforma artificial de piedra caliza prehispánica sobre la que se desplanta la iglesia y su atrio sobreelevado.', 'Resto del asentamiento maya de T''Hó aprovechado en 1729 por el gobernador Figueroa para realzar la presencia visual de la parroquia.', 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Vestigios_mayas_en_la_UADY%2C_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg', 'publico', 'publicado'),
  ('demo-object-27', 'demo-church-6', 'Torres Piramidales Gemelas de Santa Ana', 'arquitectura', 2, 'Torres campanario simétricas rematadas en empinadas pirámides cuadrangulares con pináculos decorativos.', 'Composición barroca singular del maestro cantero colonial que erigió la fachada hacia 1733, única en las parroquias de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/e/ea/Iglesia_de_Santa_Ana_-_Merida%2C_Yucatan.jpg', 'publico', 'publicado'),
  ('demo-object-28', 'demo-church-6', 'Lápida Funeraria del Gobernador Antonio de Figueroa (1733)', 'escultura', 1, 'Inscripción sepulcral grabada en cantería que certifica la tumba del militar "El Manco de Figueroa", héroe contra los piratas.', 'Instalada a la muerte del gobernador en 1733, quien dejó como última voluntad reposar bajo el presbiterio del templo que mandó construir.', 'https://upload.wikimedia.org/wikipedia/commons/0/02/Grabplatte_Johannes_Francke.JPG', 'publico', 'publicado'),
  ('demo-object-29', 'demo-church-6', 'Campana Fundida "Señora Santa Ana" (1731)', 'campana', 1, 'Campana de bronce de gran calibre colocada en la torre sur con epígrafe devocional a los padres de la Virgen María.', 'Donada por los primeros mayas artesanos del barrio para celebrar las fiestas de julio con repiques festivos.', 'https://upload.wikimedia.org/wikipedia/commons/3/3f/Santa_Ana%2C_Patrona_de_Dos_Hermanas.jpg', 'publico', 'publicado'),
  ('demo-object-30', 'demo-church-6', 'Copo y Manifestador Eucarístico Virreinal de Plata', 'orfebreria', 1, 'Sagrario portátil y custodia de plata repujada con relieves de espigas de trigo y racimos de uva.', 'Pieza litúrgica empleada en las celebraciones eucarísticas de Santa Ana desde mediados del siglo XVIII.', 'https://upload.wikimedia.org/wikipedia/commons/d/d7/Ciborium_cover_with_Polish_eagle.jpg', 'publico', 'publicado'),
  ('demo-object-31', 'demo-church-7', 'Cúpula Monumental sobre Pechinas de La Mejorada', 'arquitectura', 1, 'Gran semiesfera de mampostería maciza con linbrilla superior que corona el crucero del templo conventual.', 'Concluida hacia 1640, es una de las mayores proezas de la ingeniería abovedada franciscana del siglo XVII en Yucatán.', 'https://upload.wikimedia.org/wikipedia/commons/c/cb/Saint_John_the_Baptist_Church%2C_Cuitl%C3%A1huac%2C_Veracruz%2C_Mexico_013.jpg', 'publico', 'publicado'),
  ('demo-object-32', 'demo-church-7', 'Retablo Barroco de Columnas Salomónicas de San Diego', 'retablo', 1, 'Estructura de madera de cedro labrada con columnas entorchadas salomónicas y follajes dorados con pan de oro.', 'Altar característico del barroco novohispano donde los frailes recoletos honraban a los santos de su orden.', 'https://upload.wikimedia.org/wikipedia/commons/a/aa/Retablo_barroco_-_Museo_del_Convento_de_Santa_Clara_-_Murcia.jpg', 'publico', 'publicado'),
  ('demo-object-33', 'demo-church-7', 'Lienzo Conventual del Juicio Final y Mártires Franciscanos', 'pintura', 1, 'Óleo sobre tela de gran formato con escenas del cielo, el purgatorio y la intercesión de San Francisco.', 'Pintado por frailes artistas en el siglo XVII para recordar el voto de pobreza y la penitencia en la casa de recolección.', 'https://upload.wikimedia.org/wikipedia/commons/3/3c/Frari_%28Venice%29_nave_left_-_St.Peter_Chapel_-_The_last_Judgement_by_Andrea_Vicentino.jpg', 'publico', 'publicado'),
  ('demo-object-34', 'demo-church-7', 'Claustro Histórico y Celda de Fray Diego López de Cogolludo', 'arquitectura', 1, 'Arcadas conventuales de medio punto y patio central que hoy forman parte de la Facultad de Arquitectura de la UADY.', 'Espacio donde el célebre cronista franciscano residió como guardián y redactó los capítulos de su célebre historia de Yucatán.', 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Le_Mont-Saint-Michel_France_Detail-view-of-the-monastery-01.jpg', 'publico', 'publicado'),
  ('demo-object-35', 'demo-church-7', 'Custodia Solenme de Plata y Rubíes Virreinales', 'orfebreria', 1, 'Pieza de orfebrería novohispana en plata dorada con sol radiante y cabujones de piedras preciosas.', 'Salvaguardada por los frailes durante las turbulencias del siglo XIX y utilizada en la bendición eucarística del templo.', 'https://upload.wikimedia.org/wikipedia/commons/9/99/19th_century_Monstrance_once_belonging_to_Infanta_Benedita_of_Portugal%2C_Centro_de_Apoio_Social_de_Runa%2C_Portugal.jpg', 'publico', 'publicado'),
  ('demo-object-36', 'demo-church-8', 'Gran Portada Cóncava en Concha Abocinada', 'arquitectura', 1, 'Fachada principal resuelta como una gigantesca hornacina semicircular cóncava que abraza la plaza de acceso.', 'Diseño monumental de finales del siglo XVIII consagrado en 1796 por el obispo fray Luis de Piña y Mazo.', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Wupperfeld_Alte_Kirche_Portal.jpg', 'publico', 'publicado'),
  ('demo-object-37', 'demo-church-8', 'Lienzo Guadalupano Virreinal con las Cuatro Apariciones', 'pintura', 1, 'Pintura al óleo sobre tela del siglo XVIII con la Virgen de Guadalupe rodeada de cartelas que relatan el milagro del Tepeyac.', 'Pintado por artistas coloniales para el fomento de la devoción mariana en el barrio de los indios naboríos y tlaxcaltecas.', 'https://upload.wikimedia.org/wikipedia/commons/0/0e/Parroquia_de_San_Juan_Evangelista_y_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg', 'publico', 'publicado'),
  ('demo-object-38', 'demo-church-8', 'Órgano Tubular Neoclásico del Coro Alto', 'mobiliario', 1, 'Instrumento musical de viento con fuelles mecánicos, teclado manual y flautas de estaño y madera.', 'Instalado a finales del siglo XIX para acompañar las magnas misas de las peregrinaciones y fiestas guadalupanas.', 'https://upload.wikimedia.org/wikipedia/commons/5/5a/Everingham_Catholic_Church_Organ_and_Choir_Loft.jpg', 'publico', 'publicado'),
  ('demo-object-39', 'demo-church-8', 'Campana Guadalupana "La Tlaxcalteca" (1795)', 'campana', 1, 'Campana mayor de bronce fundida para la inauguración solemne del templo, con relieves marianos.', 'Costeada por el gremio de artesanos y descendientes de los indígenas naboríos del barrio de San Cristóbal.', 'https://upload.wikimedia.org/wikipedia/commons/b/bd/Campana_Iglesia_de_San_Javier%2C_Nasca%2C_Per%C3%BA.jpg', 'publico', 'publicado'),
  ('demo-object-40', 'demo-church-8', 'Corona Imperial y Resplandor de Plata de la Virgen', 'orfebreria', 1, 'Joya argéntea con filigrana y esmaltes donada por las asociaciones guadalupanas de la península.', 'Utilizada para la solemne coronación litúrgica en el marco del centenario de la parroquia como santuario.', 'https://upload.wikimedia.org/wikipedia/commons/1/1b/MitlaAsuncion.jpg', 'publico', 'publicado'),
  ('demo-object-41', 'demo-church-9', 'Escultura Ecuestre Virreinal de Santiago Matamoros', 'escultura', 1, 'Talla en madera policromada del apóstol Santiago con sombrero de peregrino y capa sobre caballo blanco rampante.', 'Obra escultórica del siglo XVII venerada como símbolo tutelar del barrio poniente de la ciudad de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/9/9a/Santiago_Matamoros_na_igrexa_de_Santiago_de_Traba%2C_Laxe.jpg', 'publico', 'publicado'),
  ('demo-object-42', 'demo-church-9', 'Espadaña con Cruz-Espada de la Orden de Santiago', 'arquitectura', 1, 'Campanario de tres arcos de cantería coronado con el emblema de la cruz de caballería de Santiago labrada en bulto.', 'Construida en 1637 para anunciar los oficios litúrgicos a la comunidad maya del sector poniente de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/e/e8/Holy_Cross_Catholic_Church%2C_Church_Street_and_36th_Street%2C_Latonia%2C_Covington%2C_KY.jpg', 'publico', 'publicado'),
  ('demo-object-43', 'demo-church-9', 'Pila Bautismal Colonial de los Primeros Pobladores Mayas', 'escultura', 1, 'Monolítica pila de piedra caliza con molduras labradas que sirvió para bautizar a los conversos mayas desde 1542.', 'Procedente de la primitiva ermita donde se celebró la primera misa de la Mérida hispana tras su fundación.', 'https://upload.wikimedia.org/wikipedia/commons/f/f4/St_Martin%27s_church_-_baptismal_font_-_geograph.org.uk_-_699324.jpg', 'publico', 'publicado'),
  ('demo-object-44', 'demo-church-9', 'Retablo Neoclásico del Santo Cristo de la Transfiguración', 'retablo', 1, 'Altar de maderas nobles con columnas corintias y dosel de brocado que alberga la venerada imagen del Crucificado.', 'Erigido por los gremios de zapateros, panaderos y comerciantes del barrio a mediados del siglo XIX.', 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Fra_Angelico_-_Saint_Cosmas_and_Saint_Damian_Crucifixed_and_Stoned_-_WGA0516.jpg', 'publico', 'publicado'),
  ('demo-object-45', 'demo-church-9', 'Matraca Litúrgica de Campanario de Semana Santa', 'mobiliario', 1, 'Rueda de madera de boj con martinetes que sustituye al bronce de las campanas en el duelo del Viernes Santo.', 'Mecanismo tradicional virreinal preservado por los sacristanes de Santiago para los oficios de la Semana Mayor.', 'https://upload.wikimedia.org/wikipedia/commons/8/8b/Rattle_Matraca_used_in_Lenten_ceremonies_at_Mission_Santa_Barbara%2C_ca.1900_%28CHS-4389%29.jpg', 'publico', 'publicado'),
  ('demo-object-46', 'demo-church-10', 'Calzada Virreinal de Adoquines Franceses de Brest', 'arquitectura', 1, 'Pavimento de adoquines de piedra dura colocados frente a La Ermita al inicio del Camino Real a Campeche.', 'Piedras traídas como lastre marítimo en navíos europeos durante el siglo XVIII, conservadas como testimonio del urbanismo colonial.', 'https://upload.wikimedia.org/wikipedia/commons/c/c0/Medieval-type_colonial_street%2C_Trinidad.jpg', 'publico', 'publicado'),
  ('demo-object-47', 'demo-church-10', 'Retablo Dorado de Nuestra Señora del Buen Viaje', 'retablo', 1, 'Hornacina tallada en cedro con dorado virreinal que resguarda la imagen protectora de los caminantes.', 'Mandado tallar en 1748 por el devoto comerciante Gaspar González de Ledezma en agradecimiento por prósperos viajes comerciales.', 'https://upload.wikimedia.org/wikipedia/commons/b/b7/Perpignan%2Ccath%C3%A9drale%2Cint%C3%A9rieur133_Magrana13.jpg', 'publico', 'publicado'),
  ('demo-object-48', 'demo-church-10', 'Resplandor Argénteo de Doce Estrellas de la Virgen', 'orfebreria', 1, 'Aureola y corona de plata repujada finamente labrada por plateros meridanos del gremio de San Eloy.', 'Donada en el siglo XVIII por los arrieros y conductores de diligencias que partían hacia San Francisco de Campeche.', 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Variantes_iconogr%C3%A1ficas_de_la_Virgen_Mar%C3%ADa_-_Virgen_del_Socorro_como_paradigma_de_Virgen_armada_%2821759220328%29.jpg', 'publico', 'publicado'),
  ('demo-object-49', 'demo-church-10', 'Pozo Colonial de Mampostería y Cruces Atriales de Ánimas', 'arquitectura', 3, 'Pozo artesanal con brocal de cantería y cruces de ánimas rodeadas por vegetación nativa en el jardín botánico atrial.', 'Espacio de descanso donde los viajeros abrevaban sus cabalgaduras y rezaban por las almas de sus difuntos antes de marchar.', 'https://upload.wikimedia.org/wikipedia/commons/c/c7/PikiWiki_Israel_86076_well_model_and_water_pump.jpg', 'publico', 'publicado'),
  ('demo-object-50', 'demo-church-10', 'Espadaña Almenada con Tres Campanas Coloniales', 'campana', 3, 'Campanario triangular con almenas defensivas de clara reminiscencia militar y tres campanas de afinado tañido.', 'Tocaban históricamente el Ángelus y las alertas al anochecer cuando se cerraban las verjas de salida de la ciudad.', 'https://upload.wikimedia.org/wikipedia/commons/6/6c/Church_with_three_bells_%284463268364%29.jpg', 'publico', 'publicado');
INSERT INTO public.saints (id, church_id, name, invocation, kind, description, history, cover_path, feast_day_month, feast_day_day, visibility, status)
VALUES
  ('demo-saint-1', 'demo-church-1', 'Santo Cristo de las Ampollas', 'Cristo Crucificado Milagroso de Ichmul y Mérida', 'escultura', 'Imagen de Cristo en la cruz con tez oscura y ampollas en la piel, venerada en su propia capilla dentro de la Catedral.', 'Originaria de Ichmul, tallada de un árbol que ardía sin consumirse en 1634. Llegó a Mérida en 1645 tras sobrevivir a un pavoroso incendio. Es la mayor devoción penitencial de la urbe.', 'https://upload.wikimedia.org/wikipedia/commons/1/19/Feligresa_toca_con_ramo_de_ruda_al_Cristo_de_las_ampollas%2C_Merida%2C_Yucat%C3%A1n.jpg', 9, 14, 'publico', 'publicado'),
  ('demo-saint-2', 'demo-church-1', 'San Ildefonso de Toledo', 'Arzobispo de Toledo, Confesor y Doctor de la Iglesia', 'talla', 'Efigie del santo titular de la catedral vistiendo vestiduras arzobispales, mitra y báculo en el presbiterio.', 'Patrono principal de la catedral desde su fundación en 1561 por devoción de los primeros prelados procedentes del arzobispado toledano.', 'https://upload.wikimedia.org/wikipedia/commons/6/61/Bartolome_murillo-san_ildefonso.jpg', 1, 23, 'publico', 'publicado'),
  ('demo-saint-3', 'demo-church-1', 'Nuestra Señora de Yucatán', 'Asunción de la Santísima Virgen María', 'escultura', 'Talla estofada de María elevada a los cielos por ángeles, patrona de la diócesis yucateca.', 'Venerada desde el siglo XVI en la nave mayor, protectora de las cosechas y de la paz en la península.', 'https://upload.wikimedia.org/wikipedia/commons/1/1c/TemploSanPedroAp%C3%B3stol5.JPG', 8, 15, 'publico', 'publicado'),
  ('demo-saint-4', 'demo-church-1', 'San Pedro Apóstol', 'Príncipe de los Apóstoles y Vicario de Cristo', 'escultura', 'Efigie labrada en cantería de bulto redondo portando las llaves del Reino en la Portada del Perdón.', 'Colocada a finales del siglo XVI para simbolizar la sujeción de la iglesia americana a la Cátedra de San Pedro en Roma.', 'https://upload.wikimedia.org/wikipedia/commons/f/f9/Statue_outside_Da_Nang_Cathedral_-_Da_Nang%2C_Vietnam_-_DSC02465.JPG', 6, 29, 'publico', 'publicado'),
  ('demo-saint-5', 'demo-church-1', 'San Pablo Apóstol', 'Apóstol de las Gentes y Mártir de Cristo', 'escultura', 'Efigie labrada en cantería portando la espada de la palabra de Dios en la Portada del Perdón.', 'Acompaña a San Pedro en la fachada principal como columna doctrinal de la evangelización novohispana.', 'https://upload.wikimedia.org/wikipedia/commons/a/a4/Virgen_de_la_Silla%2C_El_Barco_de_%C3%81vila.jpg', 6, 29, 'publico', 'publicado'),
  ('demo-saint-6', 'demo-church-2', 'San Ignacio de Loyola', 'Fundador de la Compañía de Jesús', 'escultura', 'Talla virreinal en madera estofada que representa a San Ignacio con casulla sacerdotal y el libro de las Constituciones.', 'Patrono tutelar del templo jesuita de Mérida desde 1618, venerado por generaciones de estudiantes del colegio anexo.', 'https://upload.wikimedia.org/wikipedia/commons/5/51/Ignatius_Loyola_-_Loyola_Academy.jpg', 7, 31, 'publico', 'publicado'),
  ('demo-saint-7', 'demo-church-2', 'San Francisco Javier', 'Apóstol de las Indias Orientales', 'escultura', 'Talla en madera policromada con sobrepelliz y crucifijo en la mano en actitud de predicar a las naciones.', 'Titular del antiguo Colegio y Universidad de San Francisco Javier que funcionó en el edificio contiguo hasta 1767.', 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Busto-relicario_de_San_Francisco_Javier%2C_Sevilla.jpg', 12, 3, 'publico', 'publicado'),
  ('demo-saint-8', 'demo-church-2', 'Nuestra Señora de la Luz', 'Madre Santísima de la Luz', 'lienzo', 'Pintura al óleo novohispana de la Virgen rescatando a un alma del abismo mientras sostiene al Niño Jesús.', 'Devoción mariana introducida por los jesuitas en Yucatán en el siglo XVIII con cofradía propia de fieles meridanos.', 'https://upload.wikimedia.org/wikipedia/commons/e/e8/Parroquia_San_Francisco_de_As%C3%ADs_%28Pachuca%29_Estado_de_Hidalgo%2CM%C3%A9xico_-_5622714629.jpg', 5, 21, 'publico', 'publicado'),
  ('demo-saint-9', 'demo-church-2', 'San Francisco de Asís', 'Patriarca Seráfico y Padre de la Tercera Orden', 'escultura', 'Escultura con sayal franciscano marrón con cordón de tres nudos y las sagradas llagas en manos y costado.', 'Entronizado solemnemente cuando los frailes franciscanos seglares recibieron el templo tras la expulsión de los jesuitas.', 'https://upload.wikimedia.org/wikipedia/commons/6/62/San_Francisco_de_As%C3%ADs_%28detalle%29%2C_Colegiata_de_Osuna.jpg', 10, 4, 'publico', 'publicado'),
  ('demo-saint-10', 'demo-church-2', 'El Dulce Nombre de Jesús', 'Santísimo Nombre de Jesús (IHS)', 'lienzo', 'Emblema radiante con el monograma de Cristo sostenido por ángeles en el arco toral del presbiterio.', 'Consagración original del templo por los padres jesuitas al erigir la capilla mayor en 1622.', 'https://upload.wikimedia.org/wikipedia/commons/4/44/San_Jos%C3%A9_con_el_Ni%C3%B1o%2C_Pedro_de_Mena.jpg', 1, 3, 'publico', 'publicado'),
  ('demo-saint-11', 'demo-church-3', 'Nuestra Señora de la Candelaria', 'Purificación de María y Presentación del Señor', 'escultura', 'Venerada talla colonial de vestir con túnica y manto bordados en seda, sosteniendo al Niño Jesús y una vela encendida.', 'Llegada a Mérida a inicios del siglo XVIII gracias a devotos canarios, congrega la fiesta patronal más vistosa del centro en febrero.', 'https://upload.wikimedia.org/wikipedia/commons/3/33/La_Virgen_de_Candelaria%2C_en_Tenerife%2C_Patrona_de_las_Islas_Canarias%2C_Espa%C3%B1a.JPG', 2, 2, 'publico', 'publicado'),
  ('demo-saint-12', 'demo-church-3', 'San Benito de Palermo', 'San Benito el Moro, Protector de los Humildes', 'escultura', 'Talla policromada de santo franciscano de tez morena sosteniendo al Niño Jesús sobre una nube de querubines.', 'Venerado tradicionalmente por la población morena y artesana del barrio desde el periodo virreinal.', 'https://upload.wikimedia.org/wikipedia/commons/b/b5/Estatua_de_Sao_Benedito.jpg', 4, 4, 'publico', 'publicado'),
  ('demo-saint-13', 'demo-church-3', 'San Blas de Sebaste', 'Obispo y Mártir, Abogado contra los Males de Garganta', 'talla', 'Imagen de bulto revestida con capa pluvial y mitra sosteniendo dos velas cruzadas.', 'Celebrado con bendición tradicional de gargantas cada 3 de febrero, al día siguiente de la Candelaria.', 'https://upload.wikimedia.org/wikipedia/commons/9/97/San_Biagio_%28La_Corsa%29.jpg', 2, 3, 'publico', 'publicado'),
  ('demo-saint-14', 'demo-church-3', 'Santa Lucía de Siracusa (Altar Lateral)', 'Mártir de la Luz y Protectora de la Vista', 'escultura', 'Imagen estofada en cedro colocada en el nicho norte del retablo mayor de La Candelaria.', 'Hermandad filial que mantenía lazos de oración recíproca con la parroquia del barrio de Santa Lucía.', 'https://upload.wikimedia.org/wikipedia/commons/e/e2/Francisco_de_Zurbar%C3%A1n_045.jpg', 12, 13, 'publico', 'publicado'),
  ('demo-saint-15', 'demo-church-3', 'El Santo Niño de la Candela', 'Infancia de Jesús Salvador del Mundo', 'escultura', 'Pequeña escultura novohispana del Niño Jesús que acompaña a la Virgen con ropaje de plata.', 'Sustraído en procesión por los niños del catecismo durante las vísperas del 2 de febrero.', 'https://upload.wikimedia.org/wikipedia/commons/4/4d/Statue_of_St_Anthony_of_Padua_with_infant_Jesus%2C_Eglise_Saint-Pierre-le-vieux_de_Strasbourg.jpg', 2, 2, 'publico', 'publicado'),
  ('demo-saint-16', 'demo-church-4', 'Santa Lucía de Siracusa', 'Virgen y Mártir, Patrona de la Vista', 'escultura', 'Talla barroca novohispana de vestir con túnica encarnada, palma del martirio y plato con los ojos.', 'Patrona del templo desde 1575, invocada fervorosamente por los meridanos para la sanación de afecciones oculares.', 'https://upload.wikimedia.org/wikipedia/commons/0/0f/Saint_Lucy._Wellcome_M0014089.jpg', 12, 13, 'publico', 'publicado'),
  ('demo-saint-17', 'demo-church-4', 'Santo Cristo de la Misericordia', 'Cristo Crucificado de la Cofradía de Morenos', 'escultura', 'Crucifijo virreinal de facciones serenas labrado en madera de cedro con perizoma estofado.', 'Perteneciente a la primitiva cofradía de morenos y pardos fundada por el encomendero Pedro García en el siglo XVI.', 'https://upload.wikimedia.org/wikipedia/commons/7/7f/Saint-Jean-aux-Bois_%2860%29%2C_Christ_en_croix_%28incomplet%29.jpg', 9, 14, 'publico', 'publicado'),
  ('demo-saint-18', 'demo-church-4', 'San Martín de Porres', 'Fraile Dominico de la Caridad', 'escultura', 'Imagen del santo mulato con hábito dominicano sosteniendo la escoba de la humildad y crucifijo.', 'Devoción arraigada en este barrio por su histórica vinculación con la comunidad de ascendencia africana de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/c/c2/Estatua_de_San_Juan_Bosco.JPG', 11, 3, 'publico', 'publicado'),
  ('demo-saint-19', 'demo-church-4', 'Nuestra Señora de los Dolores', 'La Dolorosa al Pie de la Cruz', 'escultura', 'Imagen de vestir de la Virgen María con corazón traspasado por siete espadas y manto de terciopelo negro.', 'Preside los oficios del Viernes de Dolores y las procesiones del silencio de la Semana Santa en Santa Lucía.', 'https://upload.wikimedia.org/wikipedia/commons/7/7d/Our_Lady_of_Sorrows_statue_case_in_Golgotha%2C_Holy_Sepulchre.jpg', 9, 15, 'publico', 'publicado'),
  ('demo-saint-20', 'demo-church-4', 'San José con el Niño Jesús', 'Custodio del Redentor y Patrono Universal de la Iglesia', 'talla', 'Escultura virreinal de bulto completo que muestra a San José con báculo florecido llevando de la mano al Niño.', 'Venerado por el gremio colonial de carpinteros y alarifes de Mérida que tenían sede en Santa Lucía.', 'https://upload.wikimedia.org/wikipedia/commons/2/2d/San_Jos%C3%A9_con_el_Ni%C3%B1o_%28Guatemala%29.jpg', 3, 19, 'publico', 'publicado'),
  ('demo-saint-21', 'demo-church-5', 'San Juan de Dios', 'Patrono de los Enfermos y Fundador de los Hospitalarios', 'escultura', 'Talla en cedro policromado del siglo XVII con sayal de la orden, portando una granada coronada por una cruz ardiente.', 'Titular del templo desde 1625, consolador de los enfermos ingresados en el antiguo Hospital Real de Mérida.', 'https://upload.wikimedia.org/wikipedia/commons/5/58/John_of_god_murillo.jpg', 3, 8, 'publico', 'publicado'),
  ('demo-saint-22', 'demo-church-5', 'Nuestra Señora del Rosario', 'Virgen del Rosario, Primitiva Titular del Hospital Real', 'escultura', 'Escultura mariana colonial con corona dorada y rosario de cuentas de azabache en la mano diestra.', 'Advocación primigenia bajo cuya tutela se erigió el primer hospital de la ciudad a inicios del siglo XVII.', 'https://upload.wikimedia.org/wikipedia/commons/c/cd/Matka_Bo%C5%BCa_Pompeja%C5%84ska%2C_Beata_Vergine_del_Santo_Rosario_di_Pompei%2C_Blessed_Virgin_of_the_Rosary_of_Pompei.jpg', 10, 7, 'publico', 'publicado'),
  ('demo-saint-23', 'demo-church-5', 'San Rafael Arcángel', 'Medicina de Dios y Guía de Viajeros', 'lienzo', 'Pintura al óleo novohispana que representa al arcángel con báculo de peregrino y el pez de la sanación bíblica.', 'Invocado por los médicos y cirujanos juaninos antes de realizar operaciones e intervenciones sanitarias.', 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Tobias_and_the_Archangel_Raphael_returning_with_the_Fish_-_after_Adam_Elsheimer_-_17th_c._-_Wikidata_Q26706729.jpg', 9, 29, 'publico', 'publicado'),
  ('demo-saint-24', 'demo-church-5', 'San Camilo de Lelis', 'Protector de los Agonizantes y Hospitales', 'talla', 'Imagen del santo vistiendo sotana negra con la característica cruz roja bordada en el pecho.', 'Devoción hospitalaria fomentada en el templo durante las mortíferas plagas de cólera que diezmaron la capital yucateca.', 'https://upload.wikimedia.org/wikipedia/commons/3/33/Crist%C3%B3bal_Lozano_-_Ecstasy_of_Saint_Camillus_de_Lellis_-_Google_Art_Project.jpg', 7, 14, 'publico', 'publicado'),
  ('demo-saint-25', 'demo-church-5', 'Santo Cristo de la Buena Muerte', 'Cristo del Consuelo de los Moribundos', 'escultura', 'Crucifijo de tamaño natural con cabeza inclinada hacia el fiel y acabados al óleo de profundo dramatismo.', 'Presidía la capilla ardiente y las plegarias de los últimos sacramentos en el complejo hospitalario.', 'https://upload.wikimedia.org/wikipedia/commons/b/b4/D%C3%BClmen%2C_Wegkreuz_%28Coesfelder_Stra%C3%9Fe%29_--_2012_--_3892.jpg', 11, 2, 'publico', 'publicado'),
  ('demo-saint-26', 'demo-church-6', 'Señora Santa Ana', 'Madre de la Santísima Virgen María y Abuela de Jesús', 'escultura', 'Talla barroca del siglo XVIII que representa a Santa Ana sentada con túnica verde y manto carmesí enseñando a la Virgen Niña.', 'Patrona del barrio desde 1729, festejada cada mes de julio con gremios de artesanos, vaquerías tradicionales y fuegos artificiales.', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Nacimiento_de_Jesucristo_%2823685553022%29.jpg', 7, 26, 'publico', 'publicado'),
  ('demo-saint-27', 'demo-church-6', 'San Joaquín', 'Padre de la Virgen María y Protector de los Abuelos', 'escultura', 'Escultura en madera estofada que muestra al patriarca anciano con bastón de camino y par de palomas en canastilla.', 'Forma parte del grupo escultórico titular del altar mayor comisionado por el gobernador Antonio de Figueroa en 1733.', 'https://upload.wikimedia.org/wikipedia/commons/3/37/Statue_of_Saint_Joachim_in_N%C3%A1m%C4%9B%C5%A1%C5%A5_nad_Oslavou%2C_T%C5%99eb%C3%AD%C4%8D_District.jpg', 7, 26, 'publico', 'publicado'),
  ('demo-saint-28', 'demo-church-6', 'La Niña María', 'Infancia Inmaculada de la Madre de Dios', 'escultura', 'Pequeña y primorosa talla colonial con cabellos dorados que atiende las lecciones de las Sagradas Escrituras.', 'Objeto de tierna veneración infantil y floral durante el mes de mayo en la parroquia de Santa Ana.', 'https://upload.wikimedia.org/wikipedia/commons/2/22/Statue_of_Virgin_Mary_and_Christ_child_-_geograph.org.uk_-_901675.jpg', 9, 8, 'publico', 'publicado'),
  ('demo-saint-29', 'demo-church-6', 'San Antonio de Padua', 'Doctor Evangélico y Protector de los Pobres', 'escultura', 'Talla en madera policromada con el Niño Jesús sobre el libro de los Evangelios y un lirio de pureza en su mano.', 'Venerado por las antiguas familias mayas campesinas que tributaban maíz y flores al santo taumaturgo en junio.', 'https://upload.wikimedia.org/wikipedia/commons/7/74/Juan_de_Juni-San_Antonio_de_Padua.jpg', 6, 13, 'publico', 'publicado'),
  ('demo-saint-30', 'demo-church-6', 'Señor de la Paciencia y Humildad', 'Ecce Homo Coronado de Espinas', 'talla', 'Escultura sedente de Cristo ensangrentado con caña en mano y manto púrpura en un nicho lateral.', 'Imagen procesional de gran fervor vecinal durante las procesiones de Semana Santa en el barrio norteño.', 'https://upload.wikimedia.org/wikipedia/commons/d/d7/Ecce_Homo_%28Cristo_de_las_Angustias%29.jpg', 3, 25, 'publico', 'publicado'),
  ('demo-saint-31', 'demo-church-7', 'Nuestra Señora del Tránsito', 'Asunción Gloriosa de María en Cuerpo y Alma', 'escultura', 'Imagen yacente y procesional de la Virgen dormida rodeada de querubines en madera estofada con pan de oro fino.', 'Titular original del convento franciscano de la recolección fundado en 1621 por don Pedro Gómez de Maldonado.', 'https://upload.wikimedia.org/wikipedia/commons/1/12/Iglesia_de_San_Francisco%2C_antiguo_refectorio%2C_sal%C3%B3n_De_Profundis_y_Claustro_y_Convento.JPG', 8, 15, 'publico', 'publicado'),
  ('demo-saint-32', 'demo-church-7', 'San Francisco de Asís', 'El Pobrecillo de Asís, Patriarca Seráfico', 'escultura', 'Escultura barroca de talla completa con hábito recoleto y estigmas visibles en manos, pies y costado.', 'Inspirador espiritual de la casa de recolección donde los frailes menores practicaban la penitencia y la soledad orante.', 'https://upload.wikimedia.org/wikipedia/commons/3/3d/Ermita_Nuestra_Se%C3%B1ora_de_la_Cabeza_%28Churriana_de_la_Vega%29_Granada%2CAndalucia%2CEspa%C3%B1a_%2837146017401%29.jpg', 10, 4, 'publico', 'publicado'),
  ('demo-saint-33', 'demo-church-7', 'San Diego de Alcalá', 'Fraile Menor Descalzo, Taumaturgo de los Pobres', 'talla', 'Imagen franciscana con canasta de panes transformados milagrosamente en rosas en el pliegue de su manto.', 'Patrono del retablo colateral salomónico edificado en el siglo XVII por frailes recoletos de La Mejorada.', 'https://upload.wikimedia.org/wikipedia/commons/8/8f/San_Diego_Murillo.jpg', 11, 13, 'publico', 'publicado'),
  ('demo-saint-34', 'demo-church-7', 'San Antonio Abad', 'Padre de los Monjes del Desierto y Protector de los Animales', 'escultura', 'Efigie con hábito eremítico, campana de eremita y báculo con la cruz tau griega.', 'Celebrado cada 17 de enero con la tradicional bendición de animales y ganado que congrega a fieles meridanos.', 'https://upload.wikimedia.org/wikipedia/commons/c/c7/Overasselt_%28Gld%2C_NL%29_statue_of_St.Antonius.JPG', 1, 17, 'publico', 'publicado'),
  ('demo-saint-35', 'demo-church-7', 'Nuestra Señora de la Soledad', 'Virgen de la Soledad y del Santo Entierro', 'escultura', 'Talla dolorosa virreinal vestida de luto con rosario y pañuelo entre las manos, venerada en la nave lateral.', 'Imagen procesional que encabezaba el vía crucis de los recoletos alrededor de la gran plazuela de La Mejorada.', 'https://upload.wikimedia.org/wikipedia/commons/0/02/Retablo_-_Capilla_de_la_Soledad_-_Catedral_Salamanca_%2816556566339%29.jpg', 4, 10, 'publico', 'publicado'),
  ('demo-saint-36', 'demo-church-8', 'Nuestra Señora de Guadalupe', 'Reina de México y Emperatriz de América', 'lienzo', 'Venerado lienzo monumental con la imagen de la Virgen Morena estampada en el ayate rodeada de estrellas y rayos solares.', 'Centro del santuario diocesano consagrado en 1796; recibe anualmente a decenas de miles de peregrinos y antorchistas de todo el sureste.', 'https://upload.wikimedia.org/wikipedia/commons/2/20/Virgen_de_Guadalupe_1531.jpg', 12, 12, 'publico', 'publicado'),
  ('demo-saint-37', 'demo-church-8', 'San Cristóbal Mártir', 'El Portador de Cristo y Protector de los Conductores', 'escultura', 'Escultura barroca monumental de madera estofada que muestra al gigante vadeando las aguas con el Niño Dios sobre el hombro.', 'Titular primitivo del barrio asignado a los indígenas auxiliares tlaxcaltecas y mexicas tras la conquista de Yucatán en el siglo XVI.', 'https://upload.wikimedia.org/wikipedia/commons/d/d3/Saint_Christopher_Carrying_the_Infant_Christ.jpg', 7, 25, 'publico', 'publicado'),
  ('demo-saint-38', 'demo-church-8', 'San Juan Diego Cuauhtlatoatzin', 'Mensajero de la Virgen de Guadalupe en el Tepeyac', 'escultura', 'Imagen del vidente indígena extendiendo su tilma florida cargada de rosas de Castilla.', 'Entronizado en el presbiterio tras su canonización como intercesor entrañable de los pueblos originarios de la península.', 'https://upload.wikimedia.org/wikipedia/commons/c/ca/Juan-Diego.jpg', 12, 9, 'publico', 'publicado'),
  ('demo-saint-39', 'demo-church-8', 'Señor de la Misericordia', 'Jesús de la Divina Misericordia', 'lienzo', 'Pintura de Jesús con rayos rojos y pálidos brotando de su costado abierto con la inscripción "Jesús, en ti confío".', 'Venerado con gran auge en el santuario, congrega novenarios solemnes el segundo domingo de Pascua.', 'https://upload.wikimedia.org/wikipedia/commons/a/ad/Divine_Mercy_Sanctuary_in_Vilnius4.JPG', 4, 19, 'publico', 'publicado'),
  ('demo-saint-40', 'demo-church-8', 'San Judas Tadeo', 'Apóstol y Abogado de los Casos Difíciles y Desesperados', 'escultura', 'Escultura con manto verde y túnica blanca, medalla con el rostro de Cristo en el pecho y llama del Espíritu Santo en la cabeza.', 'Atrae a miles de jóvenes y trabajadores meridanos que acuden con velas los días 28 de cada mes a pedir su mediación.', 'https://upload.wikimedia.org/wikipedia/commons/0/05/San_Judas_Tadeo%2C_de_El_Greco_%28Museo_Nacional_de_Escultura_de_Valladolid%29.JPG', 10, 28, 'publico', 'publicado'),
  ('demo-saint-41', 'demo-church-9', 'Santiago Apóstol el Mayor', 'Patrono de las Españas y del Barrio del Poniente', 'escultura', 'Magnífica talla virreinal ecuestre de madera policromada de Santiago montando un corcel blanco al galope con espada en alto.', 'Patrono tutelar del barrio desde el siglo XVI, festejado cada 25 de julio con gremios tradicionales, baile de jarana y música de viento.', 'https://upload.wikimedia.org/wikipedia/commons/a/aa/Virgen_con_el_Ni%C3%B1o%2C_Iglesia_de_San_Juan_Bautista_%28Aranda_de_Duero%29.jpg', 7, 25, 'publico', 'publicado'),
  ('demo-saint-42', 'demo-church-9', 'Santo Cristo de la Transfiguración', 'Cristo Milagroso del Barrio de Santiago', 'escultura', 'Imponente crucifijo colonial de tez morena y dulce expresión de entrega en su altar colateral de madera tallada.', 'La devoción cumbre de los santiagueros desde el siglo XVII; su fiesta de agosto congrega a los gremios de panaderos, plateros y choferes.', 'https://upload.wikimedia.org/wikipedia/commons/e/e6/Carbonero_VA.jpg', 8, 6, 'publico', 'publicado'),
  ('demo-saint-43', 'demo-church-9', 'San Isidro Labrador', 'Patrono de los Agricultores y Milperos Mayas', 'escultura', 'Talla colonial con atuendo campesino, bueyes arando la tierra y ángel que conduce la yunta.', 'Venerado por los primitivos pobladores mayas de Santiago para impetrar buenas lluvias y abundancia en la siembra de la milpa.', 'https://upload.wikimedia.org/wikipedia/commons/f/f2/Santa_Mar%C3%ADa_de_la_Cabeza%2C_Catedral_de_la_Almudena.jpg', 5, 15, 'publico', 'publicado'),
  ('demo-saint-44', 'demo-church-9', 'Nuestra Señora de la Asunción', 'Reina de los Cielos Asunta a la Gloria', 'escultura', 'Imagen mariana en madera estofada rodeada de nubes y querubines, coronada con diadema de plata.', 'Patrona de los gremios femeninos del barrio de Santiago que organizan novenas solemnes a mediados de agosto.', 'https://upload.wikimedia.org/wikipedia/commons/1/1f/Tilman_Riemenschneider_Magdalena_BNM_img01.jpg', 8, 15, 'publico', 'publicado'),
  ('demo-saint-45', 'demo-church-9', 'San Juan Bautista', 'Precursor de Cristo y Bautizador del Señor', 'talla', 'Imagen con piel de camello y báculo con filacteria que reza "Ecce Agnus Dei" señalando al cordero a sus pies.', 'Recuerda el bautismo de los primeros indígenas de T''Hó en la ermita primitiva establecida en 1542.', 'https://upload.wikimedia.org/wikipedia/commons/b/b8/San_Juan_Bautista%2C_Juan_de_Mesa.jpg', 6, 24, 'publico', 'publicado'),
  ('demo-saint-46', 'demo-church-10', 'Nuestra Señora del Buen Viaje', 'Protectora Maternal de Caminantes y Viajeros', 'escultura', 'Hermosa escultura mariana del siglo XVII con vestido y manto dorados, resplandor de plata y cetro en mano.', 'Ante ella se hincaban obligadamente los arrieros y comerciantes antes de cruzar la selva peninsular hacia San Francisco de Campeche.', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Imagen_con_Ni%C3%B1o....._Ex_-_Colegiata_de_Toro_%28_Zamora_%29_%2816177975065%29.jpg', 8, 15, 'publico', 'publicado'),
  ('demo-saint-47', 'demo-church-10', 'Santa Isabel', 'Madre del Bautista y Modelo de Hospitalidad Evangélica', 'escultura', 'Talla en madera de cedro policromada que representa a la anciana santa extendiendo sus brazos maternales.', 'Titular original de la ermita erigida hacia 1640 en el límite sur de Mérida, celebrada en noviembre.', 'https://upload.wikimedia.org/wikipedia/commons/8/89/Sodoma_-_The_Holy_Family_with_Saint_Elizabeth_and_the_Infant_Saint_John_the_Baptist_-_Walters_37522_-_View_B.jpg', 11, 5, 'publico', 'publicado'),
  ('demo-saint-48', 'demo-church-10', 'San José Caminante', 'Guía y Custodio en los Caminos y Éxodos', 'talla', 'Escultura con sombrero de viaje a la espalda, báculo de lirios y el Niño Jesús tomado con tierno amparo.', 'Invocado por los carreteros coloniales para librar las emboscadas y accidentes en las calzadas de la península.', 'https://upload.wikimedia.org/wikipedia/commons/f/f9/St._Joseph_by_Unknown_%281874%29_Control_IAS_IN000263.jpg', 3, 19, 'publico', 'publicado'),
  ('demo-saint-49', 'demo-church-10', 'Santo Cristo del Calvario de la Ermita', 'Cristo Redentor de las Ánimas del Purgatorio', 'escultura', 'Crucifijo de piedra y madera colocado en el altar del jardín atrial, frente al antiguo pozo de descanso.', 'Punto de recogimiento donde se rezan responsos solemnes durante el Janal Pixán y el tradicional Paseo de las Ánimas.', 'https://upload.wikimedia.org/wikipedia/commons/9/96/Agreda-Basilica_N._S_Milagros_13.jpg', 9, 14, 'publico', 'publicado'),
  ('demo-saint-50', 'demo-church-10', 'San Cristóbal Protector de Caminantes', 'Auxiliador en Vados y Desfiladeros Peligrosos', 'escultura', 'Pequeña talla devocional colocada en el nicho de salida del portal hacia el Camino Real a Campeche.', 'Testimonio de la devoción viandante colonial que acompañaba a las caravanas de mulas y diligencias.', 'https://upload.wikimedia.org/wikipedia/commons/8/80/Escultura_de_San_Cristobal_con_funtecilla_de_jardin%2C_pero_en_donde%3F%3F%3F_%2AFonolleres_%28Lerida%29_%2811844122994%29.jpg', 7, 25, 'publico', 'publicado');
INSERT INTO public.documents (id, church_id, title, doc_type, period_start, period_end, description, file_path, visibility, status, ocr_status)
VALUES
  ('doc-catedral-1', 'demo-church-1', 'Libro Primero de Cofradías y Fábrica de la Catedral de Mérida (1648)', 'acta', 1648, 1712, 'Manuscrito colonial encuadernado en pergamino con el asiento contable de donativos de cantería, diezmos de henequén y pagos a maestros de cantería.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-catedral-2', 'demo-church-1', 'Bula Papal de Erección "Super Speculam Militantis Ecclesiae" de Pío IV (1561)', 'decreto', 1561, 1561, 'Documento pontificio emanado de la Santa Sede que decreta la creación del Obispado de Yucatán y mandata la fábrica de la catedral en Mérida.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-catedral-3', 'demo-church-1', 'Inventario Episcopal de Alajas, Custodias y Vasos Sagrados (1788)', 'inventario', 1788, 1788, 'Catálogo pormenorizado redactado por el Cabildo Catedralicio que describe 140 piezas de platería y orfebrería novohispana de la sacristía mayor.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-jesus-1', 'demo-church-2', 'Acta de Consagración del Colegio de San Francisco Javier y Universidad (1622)', 'decreto', 1622, 1622, 'Bula y decreto episcopal que autoriza la apertura de cursos de teología, filosofía y gramática por los padres de la Compañía de Jesús en Mérida.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-jesus-2', 'demo-church-2', 'Inventario de Bienes de la Compañía de Jesús por la Expulsión de Carlos III (1767)', 'inventario', 1767, 1768, 'Acta notarial de incautación y remisión de los libros de biblioteca, lienzos flamencos e indumentaria litúrgica del templo jesuita.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-jesus-3', 'demo-church-2', 'Libro de Acuerdos de la Venerable Orden Tercera Franciscana Seglar (1795)', 'acta', 1795, 1840, 'Asiento de hermanos terciarios benefactores, cuotas de cera y celebraciones en el templo tras asumir la administración franciscana.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-candelaria-1', 'demo-church-3', 'Memoria de Donaciones del Gobernador Martín de Urzúa para la Candelaria (1706)', 'testamento', 1706, 1715, 'Escritura pública notarial donde se consigna el legado de caudales para labrar el retablo churrigueresco y dotar de ornamentos a la ermita.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-candelaria-2', 'demo-church-3', 'Libro de Hermandad de Familias Devotas de las Islas Canarias en Mérida (1742)', 'censo', 1742, 1790, 'Censo genealógico y cuotas anuales de los colonos isleños canarios asentados en el barrio que custodiaban el culto a la Candelaria.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-lucia-1', 'demo-church-4', 'Padrón y Censo de la Cofradía de Morenos y Mulatos de Santa Lucía (1790)', 'censo', 1790, 1802, 'Registro histórico poblacional que enumera familias afrodescendientes y mulatas avecindadas en el barrio con asignación de cuotas sepulcrales.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-lucia-2', 'demo-church-4', 'Decreto Capitular para el Establecimiento del Camposanto General en el Atrio (1804)', 'decreto', 1804, 1804, 'Ordenanza sanitaria del gobernador Benito Pérez Valdelomar que clausura los enterramientos intradocum e inaugura el cementerio de Santa Lucía.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-juandedios-1', 'demo-church-5', 'Libro de Entierros y Defunciones del Hospital Real de Nuestra Señora del Rosario (1695)', 'censo', 1695, 1740, 'Crónica hospitalaria manuscrita con nombres, castas y causas de fallecimiento de enfermos y soldados asistidos por los frailes juaninos.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-juandedios-2', 'demo-church-5', 'Regla y Ceremonial de la Orden Hospitalaria de San Juan de Dios en Mérida (1625)', 'cronica', 1625, 1630, 'Compendio de constituciones religiosas para la administración de boticas, enfermerías y capellanía militar anexa a la Catedral.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-santaana-1', 'demo-church-6', 'Testamento y Mandas del Brigadier don Antonio de Figueroa y Silva (1733)', 'testamento', 1733, 1733, 'Última voluntad del gobernador de Yucatán que costeó el templo de Santa Ana sobre el basamento maya y mandó sepultar su cuerpo en el presbiterio.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-santaana-2', 'demo-church-6', 'Padrón Parroquial de Familias y Milperos Mayas de la Parcialidad de Santa Ana (1750)', 'censo', 1750, 1775, 'Registro demográfico virreinal con los linajes mayas asignados a las labores agrícolas y de abasto de cantería para la ciudad de Mérida.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-mejorada-1', 'demo-church-7', 'Escritura de Donación de Solares por don Pedro Gómez de Maldonado (1621)', 'acta', 1621, 1621, 'Protocolo notarial de fundación de la Recolección Franciscana de Nuestra Señora del Tránsito de La Mejorada.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-mejorada-2', 'demo-church-7', 'Manuscrito y Apuntes de Fray Diego López de Cogolludo: Historia de Yucathan (1656)', 'cronica', 1656, 1688, 'Borradores y testimonios recopilados en su celda conventual de La Mejorada que sirvieron de base a la magna crónica publicada en Madrid.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-cristobal-1', 'demo-church-8', 'Acta de Erección Parroquial en el Pueblo de Indios Naboríos y Tlaxcaltecas (1756)', 'decreto', 1756, 1756, 'Decreto del obispado que eleva a parroquia el templo del barrio de los indígenas auxiliares aliados de la conquista de Montejo.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-cristobal-2', 'demo-church-8', 'Libro de Consagración Solemne del Templo por Fray Luis de Piña y Mazo (1796)', 'cronica', 1796, 1796, 'Relato solemne de la consagración del templo con portada en concha y entronización del lienzo virreinal de la Virgen de Guadalupe.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-santiago-1', 'demo-church-9', 'Memoria Testimonial de la Primera Misa de Fundación de Mérida en Santiago (1542)', 'cronica', 1542, 1542, 'Transcripción del acta capitular que certifica la misa celebrada por el clérigo Rodrigo Álvarez bajo enramada el 6 de enero de 1542.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-santiago-2', 'demo-church-9', 'Libro de Asiento de la Cofradía del Santo Cristo de la Transfiguración (1775)', 'acta', 1775, 1820, 'Estatutos, donaciones de plata y roles de gremios barriales para la procesión anual del venerado Cristo de Santiago.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-ermita-1', 'demo-church-10', 'Itinerario de Postas, Aranceles y Bendición del Camino Real a Campeche (1752)', 'arancel', 1752, 1770, 'Guía oficial de postas, leguas y bendición de carretas y arrieros que partían de la Ermita del Buen Viaje hacia San Francisco de Campeche.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo'),
  ('doc-ermita-2', 'demo-church-10', 'Escritura de Reedificación y Dotación por don Gaspar González de Ledezma (1748)', 'testamento', 1748, 1748, 'Legado de caudales privados para levantar el retablo dorado, el pozo de cantería y la albarrada del atrio de la Ermita de Santa Isabel.', '/documentos/documento-ejemplo.pdf', 'publico', 'publicado', 'listo');
